import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('las-heridas-de-jesus-ii', 'B',
 [dict(t=818, e=878, titulo='Dios necesita receptores', txt='Digo yo: ¿cómo nos podemos perder los milagros que Dios quiere hacer a través de la Santa Cena? Y realmente hoy es un día de reflexión, un día de pensar si realmente estamos agradando a Dios con nuestra vida, con nuestra manera de pensar, de actuar. Porque Dios quiere lo mejor para ti, pero él necesita que en tu vida haya receptores, donde tú puedas recibir la bendición de Dios. Pero si cada uno de nosotros está lejos de la bendición de Dios, ¿cómo te va a poder bendecir el Señor aunque estés aquí metido en la iglesia? Eso no es garantía tampoco. Claro, algo dice que la Palabra nunca regresa vacía y el Señor siempre va a dejar algo en tu vida; pero imagínate que tú estuvieras bien como debe ser, obediente, rechazando el pecado, rechazando la iniquidad, la fornicación, el adulterio…'),
  dict(t=1128, e=1205, titulo='Maldiciones que se vuelven bendiciones', txt='Cuando él vino a la cruz, hermano, cambió totalmente la historia para nosotros. Realmente, la bendición para los gentiles, porque usted y yo éramos gentiles y ahora somos hijos de Dios. Se abrió el panorama, se abrió el Nuevo Testamento, el nuevo pacto: un pacto de sangre con mejores promesas. Entonces dice: «Habiéndose hecho maldición por nosotros». ¿Cuántos le dan gloria a Dios de que él se hizo maldición por nosotros? Porque escrito está: «Maldito todo el que cuelga en un madero», a fin de que en Cristo Jesús la bendición de Abraham viniera a los gentiles. […] Y esas maldiciones Jesucristo las absorbió para reciclarlas y volvérselas a usted en bendiciones.'),
  dict(t=1870, e=1924, titulo='La corona de espinas', txt='Porque todo tiene un significado: un cambio de mente. Pero miren lo que aquí —porque ya ustedes lo están leyendo— dice: «Porque mis pensamientos no son vuestros pensamientos». Quiere decir que en esa corona de espinas él llevó nuestros pensamientos malos. Y quiero decirle que usted y yo tenemos más pensamientos malos que buenos: pensamientos de venganza, pensamientos que te llevan a la violencia, a la ira, pensamientos de que te quieres enseñorear de los demás. Eso no puede ser, hermano.')],
 [dict(t=981, txt='Alinearse a lo que Dios quiere se llama equilibrio espiritual. Eso lo da la Palabra. La Palabra cambia a las personas, hermano, porque es poderosa.'),
  dict(t=2203, txt='Dios lo que quiere es que vayas para adelante y que vayas para arriba. ¿Vas para arriba o vas para abajo? ¿O te estancaste? Porque, si te estancaste, vas para regreso.')],
 ['Dios necesita «receptores» en tu vida. ¿Qué hay en ti, en tus actitudes o en tus hábitos, que le estorba para recibir lo que él quiere darte?',
  'Cristo absorbió las maldiciones para volverlas bendiciones. ¿Qué parte de tu historia necesitas entregarle hoy?',
  '¿Qué pensamientos se repiten más en tu mente: los buenos o los que te llevan a la ira y a la venganza? ¿Qué podrías cambiar esta semana?'],
 inicio=497)
